#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jni.h>
#include <pthread.h>

#define MAX_HANDLERS 64
#define FEATURE_JNI_CACHE 0x01
#define FEATURE_LAZY_LOAD 0x02
#define FEATURE_STRICT_MODE 0x04

typedef struct {
    JavaVM *jvm;
    JNIEnv *env;
    jclass cached_class;
    jmethodID cached_method;
    int ref_count;
    unsigned int features;
    pthread_mutex_t lock;
} jni_context_t;

typedef struct {
    char route[256];
    jni_context_t *ctx;
    int (*handler)(jni_context_t *, const char *, char *, size_t);
} route_entry_t;

static route_entry_t routes[MAX_HANDLERS];
static int route_count = 0;

static int feature_enabled(jni_context_t *ctx, unsigned int flag) {
    return (ctx->features & flag) != 0;
}

static jclass resolve_class(jni_context_t *ctx, const char *classname) {
    if (feature_enabled(ctx, FEATURE_JNI_CACHE) && ctx->cached_class != NULL) {
        return ctx->cached_class;
    }
    JNIEnv *env = ctx->env;
    jclass cls = (*env)->FindClass(env, classname);
    if (cls == NULL) return NULL;
    if (feature_enabled(ctx, FEATURE_JNI_CACHE)) {
        ctx->cached_class = cls;
    }
    return cls;
}

static jmethodID resolve_method(jni_context_t *ctx, jclass cls, const char *name, const char *sig) {
    if (feature_enabled(ctx, FEATURE_JNI_CACHE) && ctx->cached_method != NULL) {
        return ctx->cached_method;
    }
    JNIEnv *env = ctx->env;
    jmethodID mid = (*env)->GetStaticMethodID(env, cls, name, sig);
    if (mid == NULL) return NULL;
    if (feature_enabled(ctx, FEATURE_JNI_CACHE)) {
        ctx->cached_method = mid;
    }
    return mid;
}

static int validate_input(const char *input, size_t max_len) {
    if (input == NULL) return 0;
    size_t len = strlen(input);
    if (len == 0 || len > max_len) return 0;
    for (size_t i = 0; i < len; i++) {
        if (input[i] < 0x20 || input[i] > 0x7E) return 0;
    }
    return 1;
}

static int acquire_context(jni_context_t *ctx) {
    pthread_mutex_lock(&ctx->lock);
    ctx->ref_count++;
    pthread_mutex_unlock(&ctx->lock);
    return 1;
}

static void release_context(jni_context_t *ctx) {
    pthread_mutex_lock(&ctx->lock);
    ctx->ref_count--;
    if (ctx->ref_count == 0 && !feature_enabled(ctx, FEATURE_JNI_CACHE)) {
        if (ctx->cached_class != NULL) {
            JNIEnv *env = ctx->env;
            (*env)->DeleteLocalRef(env, ctx->cached_class);
            ctx->cached_class = NULL;
            ctx->cached_method = NULL;
        }
    }
    pthread_mutex_unlock(&ctx->lock);
}

static int handle_transform(jni_context_t *ctx, const char *input, char *output, size_t out_sz) {
    if (!validate_input(input, 1024)) {
        snprintf(output, out_sz, "{\"error\":\"invalid input\"}");
        return 400;
    }
    acquire_context(ctx);
    JNIEnv *env = ctx->env;
    jclass cls = resolve_class(ctx, "com/app/Transform");
    if (cls == NULL) {
        release_context(ctx);
        snprintf(output, out_sz, "{\"error\":\"class not found\"}");
        return 500;
    }
    jmethodID mid = resolve_method(ctx, cls, "process", "(Ljava/lang/String;)Ljava/lang/String;");
    if (mid == NULL) {
        release_context(ctx);
        snprintf(output, out_sz, "{\"error\":\"method not found\"}");
        return 500;
    }
    jstring jinput = (*env)->NewStringUTF(env, input);
    jstring jresult = (jstring)(*env)->CallStaticObjectMethod(env, cls, mid, jinput);
    (*env)->DeleteLocalRef(env, jinput);
    if (jresult == NULL) {
        release_context(ctx);
        snprintf(output, out_sz, "{\"error\":\"transform failed\"}");
        return 500;
    }
    const char *result_str = (*env)->GetStringUTFChars(env, jresult, NULL);
    snprintf(output, out_sz, "{\"result\":\"%s\"}", result_str);
    (*env)->ReleaseStringUTFChars(env, jresult, result_str);
    (*env)->DeleteLocalRef(env, jresult);
    release_context(ctx);
    return 200;
}

static int handle_reload(jni_context_t *ctx, const char *input, char *output, size_t out_sz) {
    pthread_mutex_lock(&ctx->lock);
    if (ctx->cached_class != NULL) {
        JNIEnv *env = ctx->env;
        (*env)->DeleteLocalRef(env, ctx->cached_class);
        ctx->cached_class = NULL;
        ctx->cached_method = NULL;
    }
    pthread_mutex_unlock(&ctx->lock);
    snprintf(output, out_sz, "{\"status\":\"reloaded\"}");
    return 200;
}

static void register_route(const char *path, jni_context_t *ctx,
                           int (*handler)(jni_context_t *, const char *, char *, size_t)) {
    if (route_count >= MAX_HANDLERS) return;
    strncpy(routes[route_count].route, path, sizeof(routes[route_count].route) - 1);
    routes[route_count].ctx = ctx;
    routes[route_count].handler = handler;
    route_count++;
}

static int dispatch(const char *path, const char *body, char *resp, size_t resp_sz) {
    for (int i = 0; i < route_count; i++) {
        if (strcmp(routes[i].route, path) == 0) {
            return routes[i].handler(routes[i].ctx, body, resp, resp_sz);
        }
    }
    snprintf(resp, resp_sz, "{\"error\":\"not found\"}");
    return 404;
}

int init_server(unsigned int feature_flags) {
    static jni_context_t main_ctx;
    memset(&main_ctx, 0, sizeof(main_ctx));
    pthread_mutex_init(&main_ctx.lock, NULL);
    main_ctx.features = feature_flags;
    JavaVMInitArgs vm_args;
    JavaVMOption options[1];
    options[0].optionString = "-Djava.class.path=./lib";
    vm_args.version = JNI_VERSION_1_8;
    vm_args.nOptions = 1;
    vm_args.options = options;
    vm_args.ignoreUnrecognized = JNI_FALSE;
    jint rc = JNI_CreateJavaVM(&main_ctx.jvm, (void**)&main_ctx.env, &vm_args);
    if (rc != JNI_OK) return -1;
    register_route("/api/transform", &main_ctx, handle_transform);
    register_route("/api/reload", &main_ctx, handle_reload);
    return 0;
}

int main(int argc, char **argv) {
    unsigned int flags = FEATURE_JNI_CACHE | FEATURE_LAZY_LOAD;
    if (argc > 1 && strcmp(argv[1], "--strict") == 0) {
        flags |= FEATURE_STRICT_MODE;
    }
    if (init_server(flags) != 0) {
        fprintf(stderr, "Failed to initialize\n");
        return 1;
    }
    char response[4096];
    int status = dispatch("/api/transform", "hello world", response, sizeof(response));
    printf("Status: %d\nResponse: %s\n", status, response);
    return 0;
}
